const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const M = input[pos++];
const N = input[pos++];

const stock = Array.from({ length: M }, () => {
  const row = input.slice(pos, pos + N);
  pos += N;
  return row;
});

const P = input[pos++];
let sold = 0;

for (let k = 0; k < P; k++) {
  const type = input[pos++] - 1;
  const size = input[pos++] - 1;

  if (stock[type][size] > 0) {
    stock[type][size]--;
    sold++;
  }
}

console.log(sold);
